import png, numpy as np
from collections import deque
def blobs(name, color, tol=12, minsize=20):
  a = png.load(name)[:,:,:3].astype(int)
  m = (np.abs(a - np.array(color)).sum(axis=2) <= tol)
  H,W = m.shape
  seen = np.zeros_like(m)
  out=[]
  for y in range(H):
    for x in range(W):
      if m[y,x] and not seen[y,x]:
        q=deque([(y,x)]); seen[y,x]=1; pts=[]
        while q:
          cy,cx=q.popleft(); pts.append((cy,cx))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=cy+dy,cx+dx
            if 0<=ny<H and 0<=nx<W and m[ny,nx] and not seen[ny,nx]:
              seen[ny,nx]=1; q.append((ny,nx))
        if len(pts)>=minsize:
          ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
          out.append((min(xs),max(xs),min(ys),max(ys),len(pts)))
  return out
for name in ['A-101','M-101','E-101','F-101']:
  print(name)
  for b in blobs(name,(92,100,114)): print('  ',b)
